edits.content:
const int victimValue =
    pieceValue(
        victim
    );

const int targetRank =
    rankOf(
        target
    );

edits.old:
const char oldTarget =
    board[target];


const char promotedAttacker =
    seePromotionPiece(
        attacker,
        target
    );


board[from] =
    '.';

board[target] =
    promotedAttacker;


if (
    !seeKingSafe(
        board,
        whiteToCapture
    )
    ) {
    board[from] =
        attacker;

    board[target] =
        oldTarget;

    continue;
}


int promotionBonus = 0;


if (
    promotedAttacker !=
    attacker
    ) {
    promotionBonus =
        pieceValue(
            promotedAttacker
        )
        -
        pieceValue(
            attacker
        );
}

edits.new:
const char promotedAttacker =
    seePromotionPiece(
        attacker,
        target
    );


int promotionBonus = 0;


if (
    promotedAttacker !=
    attacker
    ) {
    promotionBonus =
        pieceValue(
            promotedAttacker
        )
        -
        pieceValue(
            attacker
        );
}


const int upperBound =
    victimValue
    +
    promotionBonus;


if (
    upperBound <=
    bestGain
    ) {
    continue;
}


const char oldTarget =
    board[target];


board[from] =
    '.';

board[target] =
    promotedAttacker;


if (
    !seeKingSafe(
        board,
        whiteToCapture
    )
    ) {
    board[from] =
        attacker;

    board[target] =
        oldTarget;

    continue;
}

edits.old:
const int gain =
    pieceValue(
        oldTarget
    )
    +
    promotionBonus
    -
    seeRecapture(
        board,
        target,
        !whiteToCapture
    );

edits.new:
const int gain =
    victimValue
    +
    promotionBonus
    -
    seeRecapture(
        board,
        target,
        !whiteToCapture
    );

    if (
        gain >
        bestGain
        ) {
        bestGain =
            gain;
    }


    if (
        targetRank != 0 &&
        targetRank != 7 &&
        bestGain >= victimValue
        ) {
        return bestGain;
    }
}
